const payload = $json.body ?? $json;

function parseImage(dataUrl, label) {
  if (typeof dataUrl !== 'string' || !dataUrl.startsWith('data:image/')) {
    throw new Error(label + ' 必須是 PNG、JPG 或 WebP 圖片。');
  }
  const comma = dataUrl.indexOf(',');
  const header = dataUrl.slice(0, comma);
  const mimeType = header.slice(5, header.indexOf(';'));
  const data = dataUrl.slice(comma + 1);
  if (!['image/png', 'image/jpeg', 'image/webp'].includes(mimeType) || !data) {
    throw new Error(label + ' 格式不支援。');
  }
  return { mimeType, data, dataUrl };
}

const product = parseImage(payload.productImage, '產品照');
const referenceInputs = payload.referenceImages;
if (!Array.isArray(referenceInputs) || referenceInputs.length < 1 || referenceInputs.length > 2) {
  throw new Error('風格參考圖必須是 1 到 2 張。');
}
const references = referenceInputs.map((value, index) => parseImage(value, '參考圖 ' + (index + 1)));
const photographyBrief = [
  'You are a senior commercial product photography art director.',
  'Study the product image first. It is the non-negotiable source of truth.',
  'Treat the reference images as the complete and exclusive style brief. Infer lighting, composition, camera angle, surface, background, color grade, depth of field, styling, and mood directly from them.',
  'Do not ask for or rely on a separate written style description.',
  'Write one precise production-ready image-editing prompt in English for another image model.',
  'The prompt must explicitly preserve the exact product silhouette, dimensions, cap, materials, colors, logo, typography, spelling, label layout, label text, and all packaging proportions.',
  'Do not redesign, beautify, simplify, translate, invent, or replace any product element. Do not add extra products.',
  'If product fidelity conflicts with style, product fidelity wins.',
  'Return only the final prompt. No preamble, explanation, markdown, or quotation marks.'
].join('\n');

const parts = [
  { text: photographyBrief },
  { inlineData: { mimeType: product.mimeType, data: product.data } },
  ...references.map((image) => ({ inlineData: { mimeType: image.mimeType, data: image.data } }))
];

return [{
  json: {
    requestBody: {
      contents: [{ role: 'user', parts }],
      generationConfig: {
        temperature: 0.25,
        maxOutputTokens: 2048,
        responseMimeType: 'text/plain'
      }
    },
    source: {
      productDataUrl: product.dataUrl,
      referenceDataUrls: references.map((image) => image.dataUrl)
    }
  }
}];

const promptParts = $json.candidates?.[0]?.content?.parts ?? [];
const generatedPrompt = promptParts
  .map((part) => part.text ?? '')
  .join('\n')
  .trim();

if (!generatedPrompt) {
  throw new Error('Gemini 3.7 Flash 沒有回傳攝影 prompt。');
}

const source = $('Prepare Prompt Request').first().json.source;

function parseImage(dataUrl) {
  const comma = dataUrl.indexOf(',');
  const header = dataUrl.slice(0, comma);
  return {
    mimeType: header.slice(5, header.indexOf(';')),
    data: dataUrl.slice(comma + 1)
  };
}

const product = parseImage(source.productDataUrl);
const references = source.referenceDataUrls.map(parseImage);
const fidelityLock = [
  generatedPrompt,
  '',
  'NON-NEGOTIABLE PRODUCT FIDELITY LOCK:',
  'Use the first supplied image as the exact product identity reference.',
  'Preserve every visible logo, word, spelling, typeface style, label position, package geometry, cap shape, color, material, dimension, and proportion exactly.',
  'Transfer only the photographic environment and visual treatment from the later reference images.',
  'Never redraw, reinterpret, translate, or hallucinate package text. Do not create a lookalike product.',
  'Produce one polished 16:9 commercial product photograph without captions, borders, or watermarks.'
].join('\n');

const parts = [
  { text: fidelityLock },
  { inlineData: { mimeType: product.mimeType, data: product.data } },
  ...references.map((image) => ({ inlineData: { mimeType: image.mimeType, data: image.data } }))
];

return [{
  json: {
    requestBody: {
      contents: [{ role: 'user', parts }],
      generationConfig: {
        responseModalities: ['TEXT', 'IMAGE'],
        candidateCount: 1,
        imageConfig: { aspectRatio: '16:9' }
      }
    },
    generatedPrompt
  }
}];

const parts = $json.candidates?.[0]?.content?.parts ?? [];
const imagePart = parts.find((part) => part.inlineData?.data || part.inline_data?.data);
const inlineData = imagePart?.inlineData ?? imagePart?.inline_data;

if (!inlineData?.data) {
  const modelText = parts.map((part) => part.text ?? '').join('\n').trim();
  throw new Error(modelText || 'Gemini 3.1 Flash Image 沒有回傳圖片。');
}

const mimeType = inlineData.mimeType ?? inlineData.mime_type ?? 'image/png';
return [{
  json: {
    image: 'data:' + mimeType + ';base64,' + inlineData.data,
    mimeType,
    prompt: $('Prepare Image Request').first().json.generatedPrompt,
    model: 'gemini-3.1-flash-image'
  }
}];
